description:
End-to-end tests for full search flow: server → client → UI.

## Setup
1. Start SearchRpcServer in background (port 8081)
2. Render SearchProvider + SearchPanel
3. Execute search and verify UI updates

## Test Scenarios
1. Click Search → status changes to 'searching' → results appear
2. Filter by source → filtered results
3. Pagination when > 50 results
4. Error state display
5. Auto-search toggle

## Pattern
```typescript
import { spawn } from 'bun'
import { render, screen, waitFor } from '@testing-library/react'

describe('E2E Search Flow', () => {
  let server: Subprocess

  beforeAll(async () => {
    server = spawn(['bun', 'run', 'scripts/search-server.ts'], {
      env: { ...process.env, SEARCH_SERVER_PORT: '8081' }
    })
    await new Promise(r => setTimeout(r, 2000)) // Wait for server
  })

  afterAll(() => {
    server.kill()
  })

  it('executes search and displays results', async () => {
    render(<SearchProvider><SearchPanel /></SearchProvider>)

    fireEvent.click(screen.getByRole('button', { name: /search/i }))

    await waitFor(() => {
      expect(screen.getByText(/results found/i)).toBeInTheDocument()
    }, { timeout: 10000 })
  })
})
```

