## Implementation
```typescript
Stream.async<NatsMessage, never>(
  (emit) => {
    const sub = nc.subscribe(subject)
    ;(async () => {
      for await (const msg of sub) {
        emit(Effect.succeed(Chunk.of(msg)))
      }
      emit(Effect.fail(Option.none()))
    })()
    return Effect.sync(() => sub.unsubscribe())
  },
  { bufferSize: 100, strategy: 'dropping' }
)
