## Pattern
```typescript
it.effect('delays requests when rate exceeded', () =>
  Effect.gen(function* () {
    const limiter = yield* RateLimiter.make({ limit: 10, interval: '1 minute' })
    yield* Effect.repeatN(limiter(Effect.void), 9)
    const result = yield* limiter(Effect.void)
    expect(result.delay).toEqual(Duration.zero)
    const exceeded = yield* limiter(Effect.void)
    expect(exceeded.delay).toBeGreaterThan(Duration.zero)
  })
)
