## Task
Use MutableHashMap to track per-view subscription fibers.

## Implementation
```typescript
import { MutableHashMap, Option, Fiber } from 'effect'

// In AvaClientV2 service
const fiberMap = yield* MutableHashMap.make<ViewId, Fiber.RuntimeFiber<void, AvaError>>()

// subscribeToView
const existingFiber = yield* MutableHashMap.get(fiberMap, viewId)
if (Option.isSome(existingFiber)) {
  return Effect.fail(new AvaSubscriptionError({ viewId, reason: 'Already subscribed' }))
}
const fiber = yield* subscriptionStream.pipe(Stream.runDrain, Effect.fork)
yield* MutableHashMap.set(fiberMap, viewId, fiber)

// unsubscribeFromView
const maybeFiber = yield* MutableHashMap.get(fiberMap, viewId)
yield* Option.match(maybeFiber, {
  onNone: () => Effect.void,
  onSome: (fiber) => pipe(
    Fiber.interrupt(fiber),
    Effect.andThen(MutableHashMap.remove(fiberMap, viewId))
  )
})
```

